#[test]
fn test_find_count_basic() {
    let dir = setup_workspace();

    write(dir.path().join("doc1.md"), "# Document One\n\nContent.").unwrap();
    write(dir.path().join("doc2.md"), "# Document Two\n\nContent.").unwrap();
    write(dir.path().join("doc3.md"), "# Document Three\n\nContent.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "3");
}

#[test]
fn test_find_count_with_query() {
    let dir = setup_workspace();

    write(dir.path().join("authentication.md"), "# User Authentication\n\nAuth.").unwrap();
    write(dir.path().join("database.md"), "# Database Config\n\nDB.").unwrap();
    write(dir.path().join("api.md"), "# API Endpoints\n\nAPI.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["auth", "--count"]);

    assert!(success, "stderr: {}", stderr);
    let count: usize = stdout.trim().parse().expect("count should be an integer");
    assert!(count >= 1, "should match at least authentication doc");
}

#[test]
fn test_find_count_with_roots() {
    let dir = setup_workspace();

    write(
        dir.path().join("parent.md"),
        indoc! {"
            # Parent

            [child](child)
        "},
    )
    .unwrap();

    write(dir.path().join("child.md"), "# Child\n\nChild.").unwrap();
    write(dir.path().join("orphan.md"), "# Orphan\n\nOrphan.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--roots", "--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "2");
}

#[test]
fn test_find_count_with_refs_to() {
    let dir = setup_workspace();

    write(
        dir.path().join("doc1.md"),
        indoc! {"
            # Doc One

            [target](target)
        "},
    )
    .unwrap();

    write(
        dir.path().join("doc2.md"),
        indoc! {"
            # Doc Two

            [target](target)
        "},
    )
    .unwrap();

    write(dir.path().join("doc3.md"), "# Doc Three\n\nNo refs.").unwrap();
    write(dir.path().join("target.md"), "# Target\n\nTarget.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--refs-to", "target", "--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "2");
}

